1	import { requireArea } from "@/lib/rbac";
2	import { PageHeader } from "@/components/ui/primitives";
3	import { adminListHostingInfra, adminListHostingAccounts } from "@/lib/actions-hosting";
4	import { HostingInfra } from "@/components/admin/HostingInfra";
5	import { HostingAccountsAdmin } from "@/components/admin/HostingAccountsAdmin";
6	
7	export const dynamic = "force-dynamic";
8	
9	export default async function AdminHostingPage() {
10	  await requireArea("fleet");
11	  const [{ plans, nodes }, accounts] = await Promise.all([adminListHostingInfra(), adminListHostingAccounts()]);
12	  return (
13	    <div className="space-y-6">
14	      <PageHeader title="Web Hosting" sub="Shared-hosting plans, the nodes accounts run on, and customer account operations. The provisioner is inert until ENABLE_SHARED_HOSTING is set after a security review + staging validation." />
15	      <HostingAccountsAdmin accounts={accounts} />
16	      <HostingInfra plans={plans} nodes={nodes} />
17	    </div>
18	  );
19	}
