1	"use client";
2	
3	import { useActionState, useEffect, useState, useTransition } from "react";
4	import { useRouter } from "next/navigation";
5	import {
6	  adminCreateHostingPlan,
7	  adminToggleHostingPlan,
8	  adminCreateHostingNode,
9	  adminToggleHostingNode,
10	  adminHardenHostingNode,
11	} from "@/lib/actions-hosting";
12	import { recommendHostingPlan } from "@/lib/hosting/recommend";
13	
14	const money = (c: number) => `$${(c / 100).toFixed(2)}`;
15	
16	type Plan = { id: string; slug: string; name: string; priceCents: number; diskGB: number; maxSites: number; maxDatabases: number; bandwidthTB: number; active: boolean };
17	type CapSev = "OK" | "WARN" | "CRITICAL";
18	type NodeUtil = {
19	  severity: CapSev;
20	  warnPct: number;
21	  critPct: number;
22	  dims: { dimension: string; pct: number; sev: CapSev; detail: string }[];
23	};
24	type Node = {
25	  id: string; name: string; publicIp: string; status: string; enabled: boolean; used: number; maxAccounts: number;
26	  hardenStatus: string; hardenedAt: string | null; hardenLog: string | null;
27	  util: NodeUtil;
28	};
29	
30	const SEV_BAR: Record<CapSev, string> = { OK: "#34d399", WARN: "#f59e0b", CRITICAL: "#ef4444" };
31	const SEV_TEXT: Record<CapSev, string> = { OK: "text-emerald-300", WARN: "text-amber-300", CRITICAL: "text-red-400" };
32	
33	/** Compact per-dimension utilization meters for one hosting node. */
34	function NodeUtilCell({ util }: { util: NodeUtil }) {
35	  if (!util.dims.length) return <span className="text-xs text-slate-500">—</span>;
36	  return (
37	    <div className="min-w-[180px] space-y-1.5">
38	      {util.dims.map((d) => (
39	        <div key={d.dimension} title={d.detail}>
40	          <div className="flex items-center justify-between text-[11px] text-slate-400">
41	            <span className="font-medium text-slate-300">{d.dimension}</span>
42	            <span className={SEV_TEXT[d.sev]}>{d.pct}%</span>
43	          </div>
44	          <div className="mt-0.5 h-1.5 w-full rounded-full bg-white/[0.06]">
45	            <div
46	              className="h-1.5 rounded-full transition-all"
47	              style={{ width: `${Math.min(100, d.pct)}%`, background: SEV_BAR[d.sev] }}
48	            />
49	          </div>
50	        </div>
51	      ))}
52	    </div>
53	  );
54	}
55	
56	/** A node whose hardening run is still in flight — used to drive the auto-poll. */
57	const IN_FLIGHT = (s: string) => s === "QUEUED" || s === "RUNNING";
58	
59	function HardenBadge({ status }: { status: string }) {
60	  const map: Record<string, { label: string; cls: string }> = {
61	    NONE: { label: "not hardened", cls: "text-slate-500" },
62	    QUEUED: { label: "queued", cls: "text-amber-300" },
63	    RUNNING: { label: "running…", cls: "text-sky-300" },
64	    DONE: { label: "hardened", cls: "text-emerald-300" },
65	    FAILED: { label: "failed", cls: "text-red-400" },
66	  };
67	  const m = map[status] ?? map.NONE;
68	  return <span className={`text-xs font-medium ${m.cls}`}>{m.label}</span>;
69	}
70	
71	function HardenCell({ node }: { node: Node }) {
72	  const router = useRouter();
73	  const [pending, startTransition] = useTransition();
74	  const [error, setError] = useState<string | null>(null);
75	  const [showLog, setShowLog] = useState(false);
76	  const busy = IN_FLIGHT(node.hardenStatus) || pending;
77	
78	  const run = () => {
79	    setError(null);
80	    startTransition(async () => {
81	      const res = await adminHardenHostingNode(node.id);
82	      if (res?.error) setError(res.error);
83	      else router.refresh();
84	    });
85	  };
86	
87	  return (
88	    <div className="space-y-1">
89	      <div className="flex items-center gap-2">
90	        <HardenBadge status={node.hardenStatus} />
91	        {node.hardenStatus === "DONE" && node.hardenedAt && (
92	          <span className="text-[11px] text-slate-500">{new Date(node.hardenedAt).toLocaleString()}</span>
93	        )}
94	      </div>
95	      <div className="flex items-center gap-3">
96	        <button type="button" onClick={run} disabled={busy} className="text-xs text-brand-300 hover:underline disabled:opacity-40 disabled:no-underline">
97	          {busy ? "Working…" : node.hardenStatus === "DONE" || node.hardenStatus === "FAILED" ? "Re-run harden" : "Run setup / harden"}
98	        </button>
99	        {node.hardenLog && (
100	          <button type="button" onClick={() => setShowLog((v) => !v)} className="text-xs text-slate-400 hover:underline">
101	            {showLog ? "Hide log" : "View log"}
102	          </button>
103	        )}
104	      </div>
105	      {error && <div className="text-[11px] text-red-400">{error}</div>}
106	      {showLog && node.hardenLog && (
107	        <pre className="mt-1 max-h-64 max-w-[520px] overflow-auto rounded-lg border border-white/10 bg-black/40 p-2 font-mono text-[11px] leading-relaxed text-slate-300 whitespace-pre-wrap">
108	          {node.hardenLog}
109	        </pre>
110	      )}
111	    </div>
112	  );
113	}
114	
115	export function HostingInfra({ plans, nodes }: { plans: Plan[]; nodes: Node[] }) {
116	  const [planState, planAction, planPending] = useActionState(adminCreateHostingPlan, {} as { error?: string; ok?: boolean });
117	  const [nodeState, nodeAction, nodePending] = useActionState(adminCreateHostingNode, {} as { error?: string; ok?: boolean });
118	  const router = useRouter();
119	
120	  // While any node is QUEUED/RUNNING, refresh the server component every ~5s so
121	  // the badge + timestamp + log update as the worker sweep progresses. The
122	  // interval clears itself the moment nothing is in flight.
123	  const anyInFlight = nodes.some((n) => IN_FLIGHT(n.hardenStatus));
124	  useEffect(() => {
125	    if (!anyInFlight) return;
126	    const t = setInterval(() => router.refresh(), 5000);
127	    return () => clearInterval(t);
128	  }, [anyInFlight, router]);
129	
130	  return (
131	    <div className="space-y-8">
132	      {/* Plans */}
133	      <section className="space-y-3">
134	        <h2 className="font-semibold">Hosting plans</h2>
135	        <form action={planAction} className="grid grid-cols-2 gap-3 sm:grid-cols-4">
136	          {planState?.error && <div className="col-span-full rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{planState.error}</div>}
137	          {planState?.ok && <div className="col-span-full rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">Plan created.</div>}
138	          <div><label className="label">Slug</label><input className="input" name="slug" placeholder="starter" required /></div>
139	          <div><label className="label">Name</label><input className="input" name="name" placeholder="Starter Hosting" required /></div>
140	          <div><label className="label">Price (cents/mo)</label><input className="input" name="priceCents" type="number" min={0} placeholder="299" required /></div>
141	          <div><label className="label">Disk (GB)</label><input className="input" name="diskGB" type="number" min={1} placeholder="10" required /></div>
142	          <div><label className="label">Max sites</label><input className="input" name="maxSites" type="number" min={1} placeholder="1" /></div>
143	          <div><label className="label">Max databases</label><input className="input" name="maxDatabases" type="number" min={0} placeholder="1" /></div>
144	          <div className="col-span-full"><button className="btn-primary" disabled={planPending}>{planPending ? "Creating…" : "Create plan"}</button></div>
145	        </form>
146	        {plans.length > 0 && (
147	          <div className="overflow-x-auto">
148	            <table className="w-full text-sm">
149	              <thead className="text-left text-xs text-slate-500"><tr><th className="py-1">Plan</th><th>Price</th><th>Disk</th><th>Sites/DBs</th><th>Recommended for</th><th>Status</th><th></th></tr></thead>
150	              <tbody>
151	                {plans.map((p) => {
152	                  const rec = recommendHostingPlan(p);
153	                  return (
154	                    <tr key={p.id} className="border-t border-white/5 align-top">
155	                      <td className="py-1.5">{p.name} <span className="text-xs text-slate-500">{p.slug}</span></td>
156	                      <td>{money(p.priceCents)}/mo</td>
157	                      <td>{p.diskGB} GB</td>
158	                      <td>{p.maxSites}/{p.maxDatabases}</td>
159	                      <td className="max-w-[260px] text-xs text-slate-400">
160	                        <span className="font-medium text-slate-300">{rec.tier}</span> — {rec.headline}
161	                      </td>
162	                      <td>{p.active ? <span className="text-emerald-300">active</span> : <span className="text-slate-500">off</span>}</td>
163	                      <td className="text-right"><form action={adminToggleHostingPlan.bind(null, p.id)}><button className="text-xs text-brand-300 hover:underline">{p.active ? "Disable" : "Enable"}</button></form></td>
164	                    </tr>
165	                  );
166	                })}
167	              </tbody>
168	            </table>
169	          </div>
170	        )}
171	      </section>
172	
173	      {/* Nodes */}
174	      <section className="space-y-3">
175	        <h2 className="font-semibold">Shared-hosting nodes</h2>
176	        <p className="text-xs text-slate-500">
177	          The box customer accounts live on. Its public IP is the shared A-record target every domain points at. Use
178	          <span className="font-medium text-slate-300"> Run setup / harden</span> to run
179	          <span className="font-mono"> scripts/onboard-hosting-node.sh</span> on it over Nxeon&apos;s own SSH (ModSecurity WAF + ClamAV + hardening; idempotent). The provisioner stays inert until
180	          <span className="font-mono"> ENABLE_SHARED_HOSTING=1</span> after a security review.
181	        </p>
182	        <form action={nodeAction} className="grid grid-cols-2 gap-3 sm:grid-cols-4">
183	          {nodeState?.error && <div className="col-span-full rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{nodeState.error}</div>}
184	          {nodeState?.ok && <div className="col-span-full rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">Node added.</div>}
185	          <div><label className="label">Name</label><input className="input" name="name" placeholder="shared-1" required /></div>
186	          <div><label className="label">Public IP</label><input className="input" name="publicIp" placeholder="203.0.113.7" required /></div>
187	          <div><label className="label">SSH host</label><input className="input" name="sshHost" placeholder="(defaults to public IP)" /></div>
188	          <div><label className="label">SSH port</label><input className="input" name="sshPort" type="number" placeholder="22" /></div>
189	          <div><label className="label">Root password</label><input className="input" name="rootPassword" type="password" placeholder="encrypted at rest" /></div>
190	          <div><label className="label">FQDN (CNAME target)</label><input className="input" name="hostnameFqdn" placeholder="srv1.nxeon.cloud" /></div>
191	          <div><label className="label">Max accounts</label><input className="input" name="maxAccounts" type="number" placeholder="200" /></div>
192	          <div className="col-span-full"><button className="btn-primary" disabled={nodePending}>{nodePending ? "Adding…" : "Add node"}</button></div>
193	        </form>
194	        {/* Capacity warnings — which hosting nodes are near-full, so an operator
195	            can add a node before account provisioning starts failing. */}
196	        {nodes.some((n) => n.util.severity !== "OK") && (
197	          <div className="rounded-lg border border-amber-500/30 bg-amber-500/[0.06] px-3 py-2.5">
198	            <p className="text-xs font-medium text-amber-200">Capacity warnings</p>
199	            <ul className="mt-1 space-y-0.5">
200	              {nodes
201	                .filter((n) => n.util.severity !== "OK")
202	                .map((n) => {
203	                  const worst = n.util.dims.filter((d) => d.sev !== "OK");
204	                  return (
205	                    <li key={n.id} className="text-xs text-slate-300">
206	                      <span className={SEV_TEXT[n.util.severity]}>[{n.util.severity}]</span>{" "}
207	                      <span className="font-medium">{n.name}</span> —{" "}
208	                      {worst.map((d) => `${d.dimension} ${d.pct}%`).join(", ")}
209	                    </li>
210	                  );
211	                })}
212	            </ul>
213	          </div>
214	        )}
215	        {nodes.length > 0 && (
216	          <div className="overflow-x-auto">
217	            <table className="w-full text-sm">
218	              <thead className="text-left text-xs text-slate-500"><tr><th className="py-1">Node</th><th>Public IP</th><th>Accounts</th><th className="min-w-[190px]">Utilization</th><th>Status</th><th>Hardening</th><th></th></tr></thead>
219	              <tbody>
220	                {nodes.map((n) => (
221	                  <tr key={n.id} className="border-t border-white/5 align-top">
222	                    <td className="py-1.5">
223	                      <div className="flex items-center gap-2">
224	                        <span>{n.name}</span>
225	                        {n.util.severity !== "OK" && (
226	                          <span className={`text-[10px] font-semibold uppercase ${SEV_TEXT[n.util.severity]}`}>
227	                            {n.util.severity}
228	                          </span>
229	                        )}
230	                      </div>
231	                    </td>
232	                    <td className="font-mono text-xs">{n.publicIp}</td>
233	                    <td>{n.used}/{n.maxAccounts}</td>
234	                    <td className="py-1.5"><NodeUtilCell util={n.util} /></td>
235	                    <td>{n.enabled ? <span className="text-emerald-300">{n.status.toLowerCase()}</span> : <span className="text-slate-500">disabled</span>}</td>
236	                    <td className="py-1.5"><HardenCell node={n} /></td>
237	                    <td className="text-right"><form action={adminToggleHostingNode.bind(null, n.id)}><button className="text-xs text-brand-300 hover:underline">{n.enabled ? "Disable" : "Enable"}</button></form></td>
238	                  </tr>
239	                ))}
240	              </tbody>
241	            </table>
242	          </div>
243	        )}
244	      </section>
245	    </div>
246	  );
247	}
