1	import { db } from "@/lib/db";
2	import { requireArea } from "@/lib/rbac";
3	import { PlanForm } from "@/components/PlanForm";
4	
5	export const dynamic = "force-dynamic";
6	
7	export default async function AdminPlans() {
8	  await requireArea("billing");
9	  const plans = await db.plan.findMany({
10	    include: { _count: { select: { servers: true } } },
11	    orderBy: { sortOrder: "asc" },
12	  });
13	
14	  return (
15	    <div>
16	      <h1 className="mb-6 text-2xl font-bold">Plans</h1>
17	      <div className="space-y-4">
18	        {plans.map((p) => (
19	          <div key={p.id} className="card">
20	            <p className="mb-3 text-sm text-slate-400">
21	              {p.name} · {p._count.servers} active server{p._count.servers === 1 ? "" : "s"}
22	            </p>
23	            <PlanForm plan={p} />
24	          </div>
25	        ))}
26	        <div className="card border-dashed">
27	          <p className="mb-3 text-sm text-slate-400">Create new plan</p>
28	          <PlanForm />
29	        </div>
30	      </div>
31	    </div>
32	  );
33	}
