1	"use client";
2	
3	import { useActionState, useEffect, useRef, useState, useTransition } from "react";
4	import {
5	  adminSaveEmailPlan,
6	  adminToggleEmailPlan,
7	  adminDeleteEmailPlan,
8	} from "@/lib/actions-email-hosting";
9	
10	export type EmailPlanRow = {
11	  id: string;
12	  name: string;
13	  mailboxes: number;
14	  storageGB: number;
15	  priceCents: number;
16	  termMonths: number;
17	  active: boolean;
18	  sortOrder: number;
19	};
20	
21	/**
22	 * Create/edit form for a single EmailPlan tier. Used inline on each existing
23	 * tier (behind an "Edit" toggle) and as the bottom "new tier" card.
24	 */
25	export function EmailPlanForm({ plan, onSaved }: { plan?: EmailPlanRow; onSaved?: () => void }) {
26	  const [state, action, pending] = useActionState(adminSaveEmailPlan, {} as { error?: string; ok?: boolean });
27	  const formRef = useRef<HTMLFormElement>(null);
28	
29	  useEffect(() => {
30	    if (state?.ok) {
31	      if (!plan) formRef.current?.reset();
32	      onSaved?.();
33	    }
34	  }, [state, plan, onSaved]);
35	
36	  return (
37	    <form ref={formRef} action={action} className="grid grid-cols-2 gap-3 sm:grid-cols-4">
38	      {plan && <input type="hidden" name="id" value={plan.id} />}
39	      {state?.error && (
40	        <div className="col-span-full rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
41	          {state.error}
42	        </div>
43	      )}
44	      {state?.ok && (
45	        <div className="col-span-full rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
46	          Saved.
47	        </div>
48	      )}
49	
50	      <div className="col-span-2">
51	        <label className="label">Tier name</label>
52	        <input className="input" name="name" defaultValue={plan?.name} placeholder="Business" required />
53	      </div>
54	      <div>
55	        <label className="label">Mailboxes</label>
56	        <input className="input" name="mailboxes" type="number" min={1} defaultValue={plan?.mailboxes ?? 1} required />
57	      </div>
58	      <div>
59	        <label className="label">Storage / mailbox (GB)</label>
60	        <input className="input" name="storageGB" type="number" min={1} defaultValue={plan?.storageGB ?? 10} required />
61	      </div>
62	
63	      <div>
64	        <label className="label">Price (cents)</label>
65	        <input className="input" name="priceCents" type="number" min={0} defaultValue={plan?.priceCents ?? 199} required />
66	      </div>
67	      <div>
68	        <label className="label">Term (months)</label>
69	        <input className="input" name="termMonths" type="number" min={1} max={36} defaultValue={plan?.termMonths ?? 1} required />
70	      </div>
71	      <div>
72	        <label className="label">Sort order</label>
73	        <input className="input" name="sortOrder" type="number" min={0} defaultValue={plan?.sortOrder ?? 0} />
74	      </div>
75	
76	      <div className="col-span-full flex flex-wrap items-center gap-4">
77	        <label className="flex items-center gap-2 text-sm">
78	          <input type="checkbox" name="active" defaultChecked={plan ? plan.active : true} /> Active
79	        </label>
80	        <button className="btn-primary ml-auto" disabled={pending}>
81	          {pending ? "Saving…" : plan ? "Save changes" : "Create tier"}
82	        </button>
83	      </div>
84	    </form>
85	  );
86	}
87	
88	/** Expand/collapse wrapper so each existing tier's edit form is tucked away. */
89	export function EmailPlanEditor({ plan }: { plan: EmailPlanRow }) {
90	  const [open, setOpen] = useState(false);
91	  return (
92	    <div>
93	      <button className="btn-secondary py-1 text-xs" onClick={() => setOpen((o) => !o)}>
94	        {open ? "Close" : "Edit"}
95	      </button>
96	      {open && (
97	        <div className="mt-3 border-t border-white/[0.06] pt-3">
98	          <EmailPlanForm plan={plan} onSaved={() => setOpen(false)} />
99	        </div>
100	      )}
101	    </div>
102	  );
103	}
104	
105	export function ToggleEmailPlanButton({ id, active }: { id: string; active: boolean }) {
106	  const [pending, start] = useTransition();
107	  return (
108	    <button
109	      className={active ? "btn-secondary py-1 text-xs" : "btn-primary py-1 text-xs"}
110	      disabled={pending}
111	      onClick={() => start(() => adminToggleEmailPlan(id))}
112	    >
113	      {active ? "Disable" : "Enable"}
114	    </button>
115	  );
116	}
117	
118	export function DeleteEmailPlanButton({ id, name }: { id: string; name: string }) {
119	  const [pending, start] = useTransition();
120	  const [error, setError] = useState<string | null>(null);
121	  return (
122	    <span className="inline-flex items-center gap-2">
123	      {error && <span className="text-xs text-red-400">{error}</span>}
124	      <button
125	        className="btn-danger py-1 text-xs"
126	        disabled={pending}
127	        onClick={() => {
128	          if (!confirm(`Delete tier "${name}"?`)) return;
129	          setError(null);
130	          start(async () => {
131	            const res = await adminDeleteEmailPlan(id);
132	            if (res?.error) setError(res.error);
133	          });
134	        }}
135	      >
136	        Delete
137	      </button>
138	    </span>
139	  );
140	}
