383	/**
384	 * Install the per-account Adminer database manager (or return the existing one).
385	 * Owner-or-admin + not-impersonating (same discipline as every resource-creating
386	 * action). Queues an INSTALL_DBTOOL task that drops Adminer into THIS account's
387	 * webroot at a randomized path served by the account's own FPM socket. The
388	 * customer logs in with their own SCOPED DB user, so a leaked path grants no
389	 * cross-tenant access (see the worker handler's SECURITY note). Idempotent: if the
390	 * tool is already installed, returns its path without re-queuing.
391	 */
392	export async function installDbTool(accountId: string): Promise<{ ok?: boolean; error?: string; url?: string }> {
393	  const user = await requireUser();
394	  await assertNotImpersonating();
395	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, dbToolPath: true } });
396	  if (!a) return { error: "Account not found." };
397	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
398	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
399	  if (a.dbToolPath) return { ok: true, url: a.dbToolPath };
400	  // Don't queue a second install while one is already in flight.
401	  const inFlight = await db.hostingTask.findFirst({ where: { accountId, kind: "INSTALL_DBTOOL", status: { in: ["PENDING", "RUNNING"] } } });
402	  if (inFlight) return { ok: true };
403	  const token = randomBytes(16).toString("hex").slice(0, 32); // 32 lowercase hex chars
404	  if (!isValidDbToolToken(token)) return { error: "Couldn’t start the install — try again." };
405	  const path = `/nxtools-${token}/adminer.php`;
406	  await db.hostingTask.create({ data: { accountId, kind: "INSTALL_DBTOOL", payload: JSON.stringify({ token, path }) } });
407	  revalidatePath(`/dashboard/hosting/${accountId}`);
408	  return { ok: true };
409	}
