423	export async function listHostingTasks(accountId: string): Promise<{ id: string; kind: string; status: string; result: string | null; error: string | null; createdAt: string }[]> {
424	  const user = await requireUser();
425	  // A DONE task result can carry a one-time secret (the WordPress admin password);
426	  // an impersonating admin must not read it out (audit LOW-1, same as reveal above).
427	  await assertNotImpersonating();
428	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true } });
429	  if (!a) return [];
430	  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
431	  const rows = await db.hostingTask.findMany({ where: { accountId }, orderBy: { createdAt: "desc" }, take: 8 });
432	  // A DONE result may carry a one-time secret (WordPress admin pw). Return it once,
433	  // then clear it so it isn't shown again on the next poll.
434	  const out = rows.map((t) => ({ id: t.id, kind: t.kind, status: t.status, result: t.result, error: t.error, createdAt: t.createdAt.toISOString() }));
435	  const toClear = rows.filter((t) => t.status === "DONE" && t.result);
436	  if (toClear.length) await db.hostingTask.updateMany({ where: { id: { in: toClear.map((t) => t.id) } }, data: { result: null } });
437	  return out;
438	}
