523	  const plans = all
524	    .filter((p) => p.id !== cur.id && p.priceCents >= cur.priceCents && p.diskGB >= cur.diskGB && (p.priceCents > cur.priceCents || p.diskGB > cur.diskGB))
525	    .map((p) => ({
