862	export async function createCron(accountId: string, schedule: string, command: string): Promise<HostingResult> {
863	  const ctx = await ownedSiteAccount(accountId);
864	  if ("error" in ctx) return { error: ctx.error };
865	  const { a } = ctx;
866	  const sched = String(schedule ?? "").trim();
867	  const cmd = String(command ?? "").trim();
868	  if (!isValidCronSchedule(sched)) return { error: "Enter a valid 5-field cron schedule (e.g. 0 3 * * *)." };
869	  if (!isValidCronCommand(cmd)) return { error: "Enter a command (one line, up to 500 characters, no % character)." };
870	  try {
871	    await db.$transaction(async (tx) => {
872	      const n = await tx.hostingCron.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
873	      if (n >= MAX_CRON_JOBS) throw new Error("CAP");
874	      const cron = await tx.hostingCron.create({ data: { accountId: a.id, schedule: sched, command: cmd, status: "PENDING" } });
875	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_CRON", payload: JSON.stringify({ cronId: cron.id }) } });
876	    }, { isolationLevel: "Serializable" });
877	  } catch (e) {
878	    if (e instanceof Error && e.message === "CAP") return { error: `You can schedule up to ${MAX_CRON_JOBS} cron jobs.` };
879	    return { error: "Couldn’t add the cron job — try again." };
880	  }
881	  revalidatePath(`/dashboard/hosting/${accountId}`);
882	  return { ok: true };
883	}
