3	import { PRODUCT_TERMS, ANNUAL_TERM_MONTHS, termPriceCents, type VpsTerm } from "@/lib/billing-terms";
4	
5	/**
6	 * The persuasive billing-term ladder — ONE shared, DB-fed presentation of the
7	 * "commit longer, pay less" choice, used by every non-VPS product order flow
8	 * (Shared Hosting, Business Email, Game servers, NxCloud). The VPS deploy wizard
9	 * keeps its own richer ladder because it also layers a first-term promo and
10	 * per-term add-ons on top; everything here is the clean two-choice case.
11	 *
12	 * TRUTH BY CONSTRUCTION. Every number shown is derived from the caller's real
13	 * monthly base price (`monthlyCents`, a db.*Plan.priceCents) run through
14	 * `termPriceCents` with the SAME live `annualDiscountPct` the server charges and
15	 * renews at — see lib/order.ts / renewalCharge. Nothing here is a marketing
16	 * literal: the effective $/mo, the % off, the total billed and the amount saved
17	 * are all functions of the catalogue, so a plan edit or an admin discount change
18	 * propagates automatically and the ladder can never advertise a figure checkout
19	 * won't honour.
20	 *
21	 * PERSUASION: the longest term with a real discount is badged "Best value"; the
22	 * annual term (when it isn't itself the longest) is badged "Recommended". Callers
23	 * default their selection to the recommended (annual) term — monthly stays one
24	 * click away, clearly labelled "cancel anytime", so the nudge is honest.
25	 */
26	
27	const money = (c: number) => `$${(c / 100).toFixed(2)}`;
28	
29	export function TermLadder({
30	  monthlyCents,
31	  annualDiscountPct,
32	  value,
33	  onChange,
34	  terms = PRODUCT_TERMS,
35	  columns = "sm:grid-cols-2",
36	  size = "md",
37	}: {
38	  /** The plan's real monthly base price in cents (db.*Plan.priceCents). */
39	  monthlyCents: number;
40	  /** Live admin annual discount (%), passed through untouched to termPriceCents. */
41	  annualDiscountPct: number;
42	  /** Currently-selected term in months. */
43	  value: number;
44	  onChange: (months: number) => void;
45	  /** Which term set to render. Defaults to Monthly + Annual (the non-VPS products). */
46	  terms?: VpsTerm[];
47	  /** Tailwind grid-cols utility for the ladder row. */
48	  columns?: string;
49	  size?: "sm" | "md";
50	}) {
51	  const longestMonths = terms.reduce((m, t) => Math.max(m, t.months), 0);
52	
53	  return (
54	    <div className={`grid gap-3 ${columns}`}>
55	      {terms.map((t) => {
56	        const total = termPriceCents(monthlyCents, t.months, annualDiscountPct);
57	        const perMo = Math.round(total / t.months);
58	        const monthlyRun = monthlyCents * t.months;
59	        const savings = monthlyRun - total;
60	        const disc = t.months === ANNUAL_TERM_MONTHS ? annualDiscountPct : t.discountPct;
61	        const on = value === t.months;
62	        const isMonthly = t.months === 1;
63	        const isLongest = t.months === longestMonths;
64	        const isAnnual = t.months === ANNUAL_TERM_MONTHS;
65	        // Best value = the longest term that actually discounts. Recommended =
66	        // annual, when a longer term outranks it (VPS-style 2/3-yr ladders).
67	        const ribbon = isLongest && disc > 0 ? "Best value" : isAnnual && disc > 0 ? "Recommended" : null;
68	        // Effective saving headline: annual reads "/yr", multi-year reads over the term.
69	        const savingLabel = isAnnual
70	          ? `Save ${money(savings)}/yr`
71	          : `Save ${money(savings)} over ${t.short}`;
72	
73	        return (
74	          <button
75	            key={t.months}
76	            type="button"
77	            onClick={() => onChange(t.months)}
78	            aria-pressed={on}
79	            className={`group relative rounded-2xl border ${size === "sm" ? "p-3.5" : "p-4"} text-left transition ${
80	              on
81	                ? "border-brand-400 bg-brand-500/10 ring-1 ring-brand-400/40"
82	                : ribbon
83	                  ? "border-emerald-500/25 bg-emerald-500/[0.04] hover:border-emerald-400/50"
84	                  : "border-white/10 bg-white/[0.02] hover:border-white/25"
85	            }`}
86	          >
87	            {ribbon && (
88	              <span
89	                className={`absolute -top-2.5 left-4 rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider text-white shadow ${
90	                  ribbon === "Best value" ? "bg-gradient-to-r from-emerald-500 to-teal-500" : "bg-gradient-to-r from-accent-blue to-brand-500"
91	                }`}
92	              >
93	                {ribbon}
94	              </span>
95	            )}
96	            <div className="flex items-center justify-between gap-2">
97	              <span className="text-sm font-semibold text-white">{t.label}</span>
98	              {disc > 0 && (
99	                <span className="rounded-full bg-emerald-500/15 px-1.5 py-0.5 text-[10px] font-semibold text-emerald-300">
100	                  −{disc}%
101	                </span>
102	              )}
103	            </div>
104	            <p className="mt-1.5 flex items-baseline gap-1.5">
105	              <span className={`${size === "sm" ? "text-lg" : "text-2xl"} font-bold text-white tabular-nums`}>{money(perMo)}</span>
106	              <span className="text-xs text-slate-400">/mo</span>
107	              {disc > 0 && <span className="text-xs text-slate-500 line-through tabular-nums">{money(monthlyCents)}</span>}
108	            </p>
109	            <p className="mt-1 text-[11px] text-slate-500">
110	              {money(total)} billed {isMonthly ? "monthly" : `every ${t.short}`}
111	            </p>
112	            {savings > 0 ? (
113	              <p className="mt-1 text-[11px] font-semibold text-emerald-300">{savingLabel}</p>
114	            ) : (
115	              <p className="mt-1 text-[11px] text-slate-500">Flexible — cancel anytime</p>
116	            )}
117	          </button>
118	        );
119	      })}
120	    </div>
121	  );
122	}
