/** Full editable shape of a hosting plan for the admin management UI. */
export type AdminHostingPlanRow = {
  id: string;
  slug: string;
  name: string;
  priceCents: number;
  diskGB: number;
  maxSites: number;
  maxDatabases: number;
  bandwidthTB: number;
  mailboxes: number;
  freeMigration: boolean;
  featured: boolean;
  tagline: string;
  phpVersions: string;
  active: boolean;
  sortOrder: number;
  accountCount: number;
};

/** Every hosting plan with all editable fields + live account count (admin only). */
export async function adminListHostingPlans(): Promise<AdminHostingPlanRow[]> {
  await requireArea("fleet");
  const plans = await db.hostingPlan.findMany({
    orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }],
    include: { _count: { select: { accounts: true } } },
  });
  return plans.map((p) => ({
    id: p.id,
    slug: p.slug,
    name: p.name,
    priceCents: p.priceCents,
    diskGB: p.diskGB,
    maxSites: p.maxSites,
    maxDatabases: p.maxDatabases,
    bandwidthTB: p.bandwidthTB,
    mailboxes: p.mailboxes,
    freeMigration: p.freeMigration,
    featured: p.featured,
    tagline: p.tagline,
    phpVersions: p.phpVersions,
    active: p.active,
    sortOrder: p.sortOrder,
    accountCount: p._count.accounts,
  }));
}

/** Normalize a comma-separated PHP-version list to distinct, valid `\d.\d` tokens. */
function normalizePhpVersions(raw: string): string {
  const seen = new Set<string>();
  for (const tok of raw.split(",").map((s) => s.trim()).filter(Boolean)) {
    if (/^\d\.\d$/.test(tok)) seen.add(tok);
  }
  return [...seen].join(",");
}

/**
 * Create OR edit a hosting plan (unified, like adminSaveEmailPlan). A hidden `id`
 * switches to edit. Surfaces + persists every quota the plan cards read — disk,
 * websites, databases, bandwidth, mailboxes — plus price and marketing flags. No
 * charge logic here: price is just stored, read back at order/renewal unchanged.
 */
export async function adminSaveHostingPlan(_prev: unknown, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  const admin = await requireArea("fleet");
  const id = String(formData.get("id") ?? "").trim() || null;
  const slug = String(formData.get("slug") ?? "").trim().toLowerCase();
  const name = String(formData.get("name") ?? "").trim();
  const priceCents = Math.round(Number(formData.get("priceCents") ?? 0));
  const diskGB = Math.round(Number(formData.get("diskGB") ?? 0));
  const maxSites = Math.round(Number(formData.get("maxSites") ?? 1));
  const maxDatabases = Math.round(Number(formData.get("maxDatabases") ?? 1));
  const bandwidthTB = Number(formData.get("bandwidthTB") ?? 1);
  const mailboxes = Math.round(Number(formData.get("mailboxes") ?? 1));
  const tagline = String(formData.get("tagline") ?? "").trim();
  const phpVersions = normalizePhpVersions(String(formData.get("phpVersions") ?? "8.3")) || "8.3";
  const sortOrder = Math.round(Number(formData.get("sortOrder") ?? 0)) || 0;
  const freeMigration = formData.get("freeMigration") === "on";
  const featured = formData.get("featured") === "on";
  const active = formData.get("active") === "on";

  if (!/^[a-z][a-z0-9-]{1,31}$/.test(slug)) return { error: "Slug: lowercase letters, digits, dashes (2–32 chars)." };
  if (!name) return { error: "Enter a plan name." };
  if (priceCents < 0) return { error: "Price can’t be negative." };
  if (diskGB < 1) return { error: "Disk (storage) must be at least 1 GB." };
  if (maxSites < 1) return { error: "Websites must be at least 1." };
  if (maxDatabases < 0) return { error: "Databases can’t be negative." };
  if (!Number.isFinite(bandwidthTB) || bandwidthTB < 0) return { error: "Bandwidth can’t be negative." };
  if (mailboxes < -1) return { error: "Mailboxes must be -1 (unlimited) or more." };

  // Slug is @unique — reject a collision with a DIFFERENT plan (self is fine on edit).
  const bySlug = await db.hostingPlan.findUnique({ where: { slug } });
  if (bySlug && bySlug.id !== id) return { error: "A plan with that slug already exists." };

  const data = {
    slug, name, priceCents, diskGB, maxSites, maxDatabases, bandwidthTB,
    mailboxes, freeMigration, featured, tagline, phpVersions, active, sortOrder,
  };

  if (id) {
    const existing = await db.hostingPlan.findUnique({ where: { id } });
    if (!existing) return { error: "Plan not found." };
    await db.hostingPlan.update({ where: { id }, data });
  } else {
    await db.hostingPlan.create({ data });
  }

  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: id ? "hostingplan.update" : "hostingplan.create",
      detail: `${name} (${slug}) — ${diskGB}GB / ${maxSites} site(s) / ${maxDatabases} db / ${bandwidthTB}TB (${(priceCents / 100).toFixed(2)}/mo)`,
    },
  }).catch(() => {});
  revalidatePath("/admin/hosting");
  return { ok: true };
}

/** Delete a hosting plan. Refused while any account references it (disable instead). */
export async function adminDeleteHostingPlan(id: string): Promise<{ error?: string; ok?: boolean }> {
  const admin = await requireArea("fleet");
  const plan = await db.hostingPlan.findUnique({
    where: { id },
    include: { _count: { select: { accounts: true } } },
  });
  if (!plan) return { error: "Plan not found." };
  if (plan._count.accounts > 0) {
    return { error: `Can’t delete — ${plan._count.accounts} account(s) use this plan. Disable it instead.` };
  }
  await db.hostingPlan.delete({ where: { id } });
  await db.auditLog.create({ data: { userId: admin.id, action: "hostingplan.delete", detail: plan.name } }).catch(() => {});
  revalidatePath("/admin/hosting");
  return { ok: true };
}

