"use client";

import { useActionState, useEffect, useRef, useState, useTransition } from "react";
import {
  adminSaveHostingPlan,
  adminToggleHostingPlan,
  adminDeleteHostingPlan,
  type AdminHostingPlanRow,
} from "@/lib/actions-hosting";

export type HostingPlanRow = AdminHostingPlanRow;

/**
 * Create/edit form for a single shared-hosting plan. Used inline on each existing
 * plan (behind an "Edit" toggle) and as the bottom "new plan" card — the same
 * pattern as EmailPlanControls / GamePlanControls. Every quota that customer plan
 * cards read (disk/storage, websites, databases, bandwidth, mailboxes) is exposed
 * and editable here. All values are DB-fed via hostingPlan; nothing is hard-coded.
 */
export function HostingPlanForm({ plan, onSaved }: { plan?: HostingPlanRow; onSaved?: () => void }) {
  const [state, action, pending] = useActionState(adminSaveHostingPlan, {} as { error?: string; ok?: boolean });
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    if (state?.ok) {
      if (!plan) formRef.current?.reset();
      onSaved?.();
    }
  }, [state, plan, onSaved]);

  return (
    <form ref={formRef} action={action} className="grid grid-cols-2 gap-3 sm:grid-cols-4">
      {plan && <input type="hidden" name="id" value={plan.id} />}
      {state?.error && (
        <div className="col-span-full rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {state.error}
        </div>
      )}
      {state?.ok && (
        <div className="col-span-full rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
          Saved.
        </div>
      )}

      <div className="col-span-2">
        <label className="label">Plan name</label>
        <input className="input" name="name" defaultValue={plan?.name} placeholder="Starter Hosting" required />
      </div>
      <div>
        <label className="label">Slug</label>
        <input className="input" name="slug" defaultValue={plan?.slug} placeholder="starter" required />
      </div>
      <div>
        <label className="label">Price (cents/mo)</label>
        <input className="input" name="priceCents" type="number" min={0} defaultValue={plan?.priceCents ?? 299} required />
      </div>

      <div>
        <label className="label">Storage / disk (GB)</label>
        <input className="input" name="diskGB" type="number" min={1} defaultValue={plan?.diskGB ?? 10} required />
      </div>
      <div>
        <label className="label">Websites</label>
        <input className="input" name="maxSites" type="number" min={1} defaultValue={plan?.maxSites ?? 1} required />
      </div>
      <div>
        <label className="label">Databases</label>
        <input className="input" name="maxDatabases" type="number" min={0} defaultValue={plan?.maxDatabases ?? 1} required />
      </div>
      <div>
        <label className="label">Bandwidth (TB)</label>
        <input className="input" name="bandwidthTB" type="number" min={0} step="0.5" defaultValue={plan?.bandwidthTB ?? 1} required />
      </div>

      <div>
        <label className="label">Mailboxes (-1 = ∞)</label>
        <input className="input" name="mailboxes" type="number" min={-1} defaultValue={plan?.mailboxes ?? 1} required />
      </div>
      <div>
        <label className="label">PHP versions</label>
        <input className="input" name="phpVersions" defaultValue={plan?.phpVersions ?? "8.3"} placeholder="8.1,8.2,8.3" />
      </div>
      <div>
        <label className="label">Sort order</label>
        <input className="input" name="sortOrder" type="number" min={0} defaultValue={plan?.sortOrder ?? 0} />
      </div>
      <div className="col-span-2 sm:col-span-1">
        <label className="label">Tagline</label>
        <input className="input" name="tagline" defaultValue={plan?.tagline} placeholder="Great for a first site" />
      </div>

      <div className="col-span-full flex flex-wrap items-center gap-4 pt-1">
        <label className="flex items-center gap-2 text-sm text-slate-300">
          <input type="checkbox" name="active" defaultChecked={plan ? plan.active : true} /> Active
        </label>
        <label className="flex items-center gap-2 text-sm text-slate-300">
          <input type="checkbox" name="featured" defaultChecked={plan ? plan.featured : false} /> Featured
        </label>
        <label className="flex items-center gap-2 text-sm text-slate-300">
          <input type="checkbox" name="freeMigration" defaultChecked={plan ? plan.freeMigration : false} /> Free migration
        </label>
        <button className="btn-primary ml-auto" disabled={pending}>
          {pending ? "Saving…" : plan ? "Save changes" : "Create plan"}
        </button>
      </div>
    </form>
  );
}

/** Expand/collapse wrapper so each existing plan's edit form is tucked away. */
export function HostingPlanEditor({ plan }: { plan: HostingPlanRow }) {
  const [open, setOpen] = useState(false);
  return (
    <div>
      <button className="btn-secondary py-1 text-xs" onClick={() => setOpen((o) => !o)}>
        {open ? "Close" : "Edit"}
      </button>
      {open && (
        <div className="mt-3 border-t border-white/[0.06] pt-3">
          <HostingPlanForm plan={plan} onSaved={() => setOpen(false)} />
        </div>
      )}
    </div>
  );
}

export function ToggleHostingPlanButton({ id, active }: { id: string; active: boolean }) {
  const [pending, start] = useTransition();
  return (
    <button
      className={active ? "btn-secondary py-1 text-xs" : "btn-primary py-1 text-xs"}
      disabled={pending}
      onClick={() => start(() => adminToggleHostingPlan(id))}
    >
      {active ? "Disable" : "Enable"}
    </button>
  );
}

export function DeleteHostingPlanButton({ id, name }: { id: string; name: string }) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  return (
    <span className="inline-flex items-center gap-2">
      {error && <span className="text-xs text-red-400">{error}</span>}
      <button
        className="btn-danger py-1 text-xs"
        disabled={pending}
        onClick={() => {
          if (!confirm(`Delete plan "${name}"?`)) return;
          setError(null);
          start(async () => {
            const res = await adminDeleteHostingPlan(id);
            if (res?.error) setError(res.error);
          });
        }}
      >
        Delete
      </button>
    </span>
  );
}

import { Badge, fmtMoney } from "@/components/ui/primitives";
import {
  HostingPlanForm,
  HostingPlanEditor,
  ToggleHostingPlanButton,
  DeleteHostingPlanButton,
  type HostingPlanRow,
} from "@/components/admin/HostingPlanControls";

/**
 * Admin management for shared-hosting plans — same card + inline-editor pattern as
 * the VPS / Business Email / Game plan pages (app/admin/email-plans, game-plans).
 * Each plan shows its full spec sheet (storage/disk, websites, databases,
 * bandwidth, mailboxes, price) up front, with a tidy edit form behind "Edit" and a
 * "new plan" card at the bottom. Everything is DB-fed via hostingPlan.
 */
export function HostingPlansAdmin({ plans }: { plans: HostingPlanRow[] }) {
  return (
    <section className="space-y-3">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h2 className="text-lg font-semibold text-white">Shared hosting plans</h2>
          <p className="mt-1 text-sm text-slate-400">
            The tiers customers order a site on. Storage and every quota below are what the plan cards advertise and
            what each new account is provisioned with.
          </p>
        </div>
        <Badge tone="brand">{plans.length} plan{plans.length === 1 ? "" : "s"}</Badge>
      </div>

      <div className="space-y-3">
        {plans.length === 0 && <p className="text-sm text-slate-500">No plans yet — add one below.</p>}
        {plans.map((p) => (
          <div key={p.id} className="card">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <div className="min-w-0">
                <div className="flex flex-wrap items-center gap-2">
                  <span className="font-semibold text-white">{p.name}</span>
                  <span className="text-xs text-slate-500">{p.slug}</span>
                  <Badge tone={p.active ? "green" : "slate"}>{p.active ? "Active" : "Disabled"}</Badge>
                  {p.featured && <Badge tone="brand">Featured</Badge>}
                  {p.freeMigration && <Badge tone="slate">Free migration</Badge>}
                  {p.accountCount > 0 && (
                    <Badge tone="slate">{p.accountCount} account{p.accountCount === 1 ? "" : "s"}</Badge>
                  )}
                </div>
                {/* Spec sheet — storage first (board 349sjj), then the other quotas. */}
                <div className="mt-2 flex flex-wrap gap-1.5">
                  <Spec label="Storage" value={`${p.diskGB} GB`} strong />
                  <Spec label="Websites" value={String(p.maxSites)} />
                  <Spec label="Databases" value={String(p.maxDatabases)} />
                  <Spec label="Bandwidth" value={`${p.bandwidthTB} TB`} />
                  <Spec label="Mailboxes" value={p.mailboxes === -1 ? "Unlimited" : String(p.mailboxes)} />
                  <Spec label="PHP" value={p.phpVersions || "—"} />
                </div>
                <p className="mt-2 text-sm text-slate-400">
                  <span className="text-white">{fmtMoney(p.priceCents)}</span> / mo
                  {p.tagline ? <span className="text-slate-500"> · {p.tagline}</span> : null}
                </p>
              </div>
              <div className="flex flex-wrap items-center gap-2">
                <ToggleHostingPlanButton id={p.id} active={p.active} />
                <DeleteHostingPlanButton id={p.id} name={p.name} />
              </div>
            </div>
            <div className="mt-3">
              <HostingPlanEditor plan={p} />
            </div>
          </div>
        ))}
      </div>

      <div className="card mt-4">
        <h3 className="mb-3 text-base font-semibold text-white">New plan</h3>
        <HostingPlanForm />
      </div>
    </section>
  );
}

/** A single spec chip — label + value, storage rendered a touch stronger. */
function Spec({ label, value, strong = false }: { label: string; value: string; strong?: boolean }) {
  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-md border px-2 py-0.5 text-[11px] ${
        strong ? "border-brand-500/30 bg-brand-500/10 text-brand-100" : "border-white/[0.06] bg-white/[0.02] text-slate-300"
      }`}
    >
      <span className="text-slate-500">{label}</span>
      <span className="font-medium">{value}</span>
    </span>
  );
}

